create or replace view public.institution_explorer_de_v1 with(security_invoker=true) as select i.id institution_id,i.country_code,i.slug,i.canonical_name,i.institution_kind,i.ownership_type,i.website_url,coalesce(programmes.program_count,0)::integer program_count,coalesce(locations.location_count,0)::integer campus_count,coalesce(locations.city_count,0)::integer city_count,coalesce(locations.city_names,array[]::text[]) city_names from catalog.institutions i left join lateral(select count(*)::integer program_count from catalog.programmes p where p.institution_id=i.id and p.status='active') programmes on true left join lateral(select count(*)::integer location_count,count(distinct l.city_name)::integer city_count,coalesce(array_agg(distinct l.city_name order by l.city_name) filter(where l.city_name is not null),array[]::text[]) city_names from public.institution_location_de_v1 l where l.institution_id=i.id) locations on true where i.country_code='DE' and i.status<>'inactive' and i.slug is not null; revoke all on public.institution_explorer_de_v1 from public,anon,authenticated; grant select on public.institution_explorer_de_v1 to service_role; create or replace view public.institution_detail_de_v1 with(security_invoker=true) as select i.id institution_id,i.country_code,i.slug,i.canonical_name,i.institution_kind,i.ownership_type,i.website_url,i.status,coalesce(programmes.program_count,0)::integer program_count,coalesce(locations.location_count,0)::integer campus_count,coalesce(locations.city_count,0)::integer city_count,coalesce(locations.city_names,array[]::text[]) city_names,null::text cricos_provider_code,null::text cricos_source_url,coalesce(locations.campus_locations,'[]'::jsonb) campus_locations,'[]'::jsonb study_areas,'[]'::jsonb programme_types,'[]'::jsonb programme_preview from catalog.institutions i left join lateral(select count(*)::integer program_count from catalog.programmes p where p.institution_id=i.id and p.status='active') programmes on true left join lateral(select count(*)::integer location_count,count(distinct l.city_name)::integer city_count,coalesce(array_agg(distinct l.city_name order by l.city_name) filter(where l.city_name is not null),array[]::text[]) city_names,coalesce(jsonb_agg(jsonb_build_object('id',l.campus_id,'name',l.name,'city',l.city_name,'citySlug',l.city_slug,'reportedCity',l.reported_city,'region',l.region,'address',l.address_line,'postalCode',l.postal_code,'officialUrl',l.official_url) order by l.campus_id),'[]'::jsonb) campus_locations from public.institution_location_de_v1 l where l.institution_id=i.id) locations on true where i.country_code='DE' and i.status<>'inactive' and i.slug is not null; revoke all on public.institution_detail_de_v1 from public,anon,authenticated; grant select on public.institution_detail_de_v1 to service_role; do $$ declare c int; begin select count(*) into c from public.institution_explorer_de_v1; if c<>12 then raise exception 'Expected 12 DE explorer rows, found %',c; end if; select count(*) into c from public.institution_detail_de_v1 where campus_count<1 or jsonb_array_length(campus_locations)<1; if c>0 then raise exception 'DE details missing location %',c; end if; select count(*) into c from public.institution_detail_de_v1 where program_count<>0 or jsonb_array_length(programme_preview)<>0; if c>0 then raise exception 'DE programme catalogue expected pending %',c; end if; end $$;;
